<?php $tr=static fn(string $key)=>lang('Examination.'.$key);$signed=!empty($clinical_note_signed);$signature=is_array($clinical_note_signature??null)?$clinical_note_signature:null;$addenda=is_array($clinical_note_addenda??null)?$clinical_note_addenda:[]; ?>
<section class="record-panel clinical-note-governance"><header class="clinical-panel-heading"><h2><?= esc($tr('clinical_note_governance')) ?></h2><span class="clinical-record-status <?= $signed?'':'clinical-record-status--warning' ?>"><?= esc($tr($signed?'note_signed_locked':'note_unsigned')) ?></span></header>
<?php if($signed&&$signature): ?><p class="clinical-note-message"><?= esc($tr('signed_note_help')) ?></p><dl class="settings-summary"><div><dt><?= esc($tr('signed_by')) ?></dt><dd><?= esc($signature['signed_by_name']??'') ?></dd></div><div><dt><?= esc($tr('signed_at')) ?></dt><dd><?= esc(formatDateTime($signature['signed_at']??'')) ?></dd></div></dl><?php if($addenda): ?><h3><?= esc($tr('note_addenda')) ?></h3><?php foreach($addenda as $addendum): ?><article class="clinical-addendum"><header><strong><?= esc($addendum['reason']??'') ?></strong><small><?= esc(($addendum['added_by_name']??'').' · '.formatDateTime($addendum['created_at']??'')) ?></small></header><p class="clinical-narrative"><?= esc($addendum['body']??'') ?></p></article><?php endforeach;endif; ?>
<?php if(has_permission('examinations','edit')): ?><form method="post" action="<?= base_url('examination/'.(int)$examination['id'].'/clinical-note/addendum') ?>" class="clinical-note-form"><?= csrf_field() ?><h3><?= esc($tr('add_note_addendum')) ?></h3><div class="form-field"><label for="note_addendum_reason"><?= esc($tr('addendum_reason')) ?></label><input id="note_addendum_reason" name="reason" maxlength="255" value="<?= esc(old('reason'),'attr') ?>" required></div><div class="form-field"><label for="note_addendum_body"><?= esc($tr('addendum_text')) ?></label><textarea id="note_addendum_body" name="body" rows="4" maxlength="10000" required><?= esc(old('body')) ?></textarea></div><button type="submit" class="button primary"><?= esc($tr('append_addendum')) ?></button></form><?php endif; ?>
<?php else: ?><p class="clinical-note-message clinical-note-message--warning"><?= esc($tr('unsigned_note_help')) ?></p><?php if(($status_key??'')==='completed'&&has_permission('examinations','edit')): ?><form method="post" action="<?= base_url('examination/'.(int)$examination['id'].'/clinical-note/sign') ?>" class="clinical-note-form"><?= csrf_field() ?><label class="clinical-attestation"><input type="checkbox" name="attest" value="1" required><span><?= esc($tr('sign_attestation')) ?></span></label><button class="button primary" type="submit"><?= esc($tr('sign_and_lock_note')) ?></button></form><?php elseif(($status_key??'')!=='completed'): ?><p class="clinical-empty"><?= esc($tr('complete_before_signing')) ?></p><?php endif;endif; ?></section>
